.jui-promotion-code {
  --promotion-accent: #0074d4;
  --promotion-surface: #fff;
  --promotion-text: #303030;
  --promotion-idle: #f3f3f3;
  --promotion-border: #dedede;
  --promotion-placeholder: #787878;
  --promotion-error: #c53030;
  color-scheme: light;
  --promotion-ring: rgba(50, 151, 211, .72);
  width: 100%; color: var(--promotion-text);
  font: 14px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Ubuntu, sans-serif;
}
.jui-promotion-code-field { position: relative; display: inline-grid; min-width: 35%; max-width: 100%; vertical-align: top; transition: min-width 200ms ease-out; }
.jui-promotion-code[data-expanded="true"] .jui-promotion-code-field { min-width: 100%; }
.jui-promotion-code-measure { grid-area: 1/1; visibility: hidden; height: 36px; padding-inline: 12px; white-space: nowrap; font-weight: 500; overflow: hidden; }
.jui-promotion-code input { grid-area: 1/1; box-sizing: border-box; width: 100%; min-width: 0; height: 36px; margin: 0; padding: 8px 12px; border: 0; border-radius: 12px; outline: none; background: var(--promotion-idle); color: inherit; font: inherit; cursor: pointer; transition: padding 200ms ease-out, background 200ms ease-out, box-shadow 200ms ease-out; }
.jui-promotion-code input::placeholder { color: var(--promotion-text); opacity: 1; font-weight: 500; transition: color 200ms ease-out; }
.jui-promotion-code[data-expanded="false"] input:hover { background: color-mix(in srgb, var(--promotion-idle), var(--promotion-text) 4%); }
.jui-promotion-code[data-expanded="true"] input { background: var(--promotion-surface); box-shadow: 0 0 0 1px var(--promotion-border), 0 1px 1px #00000012; cursor: text; }
.jui-promotion-code[data-expanded="true"] input::placeholder { color: var(--promotion-placeholder); font-weight: 400; }
.jui-promotion-code[data-has-value="true"] input { padding-inline-end: 100px; }
.jui-promotion-code .jui-promotion-code-field:focus-within input { box-shadow: 0 1px 1px #00000012, 0 0 0 3px var(--promotion-ring); }
.jui-promotion-code-apply { position: absolute; inset-inline-end: 12px; top: 0; bottom: 0; padding: 0; border: 0; background: transparent; color: var(--promotion-accent); font: inherit; font-weight: 500; opacity: 0; transform: scale(.8); pointer-events: none; transition: opacity 300ms ease, transform 300ms ease; }
.jui-promotion-code[data-has-value="true"] .jui-promotion-code-apply { opacity: 1; transform: scale(1); pointer-events: auto; cursor: pointer; }
.jui-promotion-code-apply:focus-visible { outline: 2px solid var(--promotion-accent); outline-offset: 2px; border-radius: 3px; }
.jui-promotion-code-apply:disabled { cursor: default; }
.jui-promotion-code[data-disabled] { opacity: .5; }
.jui-promotion-code[data-disabled] input { cursor: default; }
.jui-promotion-code-error { display: block; margin-top: 8px; color: var(--promotion-error); font-size: 13px; }
.jui-promotion-code input[aria-invalid="true"] { box-shadow: 0 0 0 1px var(--promotion-error); }
@media (prefers-reduced-motion: reduce) { .jui-promotion-code-field, .jui-promotion-code input, .jui-promotion-code input::placeholder, .jui-promotion-code-apply { transition: none; } }
.jui-promotion-code[data-has-value="false"] .jui-promotion-code-apply { opacity: 0; visibility: hidden; pointer-events: none; }

.jui-promotion-code[data-theme="dark"] {
  color-scheme: dark;
  --promotion-accent: #80bdff;
  --promotion-surface: #252629;
  --promotion-text: #eeeeef;
  --promotion-idle: #303135;
  --promotion-border: #48494e;
  --promotion-placeholder: #a2a3aa;
  --promotion-error: #ff9494;
  --promotion-ring: rgba(100, 170, 240, .65);
}
.jui-promotion-code { --promotion-success: #278354; }
.jui-promotion-code[data-theme="dark"] { --promotion-success: #75d5a1; }
.jui-promotion-code-spinner { display: inline-block; width: 14px; height: 14px; vertical-align: middle; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: jui-promotion-code-spin 650ms linear infinite; }
.jui-promotion-code-confirmation { display: inline-flex; align-items: center; gap: 4px; }
.jui-promotion-code[data-status="success"] .jui-promotion-code-apply { color: var(--promotion-success); opacity: 1; }
.jui-promotion-code[data-status="loading"] .jui-promotion-code-apply { opacity: 1; visibility: visible; }
.jui-promotion-code[data-status="success"] input { box-shadow: 0 0 0 1px var(--promotion-success); }
.jui-promotion-code[data-status="error"] .jui-promotion-code-field { animation: jui-promotion-code-shake 240ms ease-out; }
.jui-promotion-code[data-status="error"] .jui-promotion-code-field input { box-shadow: 0 0 0 2px var(--promotion-error); }
.jui-promotion-code-announcement { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@keyframes jui-promotion-code-spin { to { transform: rotate(360deg); } }
@keyframes jui-promotion-code-shake { 25% { transform: translateX(-3px); } 75% { transform: translateX(3px); } }
@media (prefers-reduced-motion: reduce) { .jui-promotion-code-spinner, .jui-promotion-code[data-status="error"] .jui-promotion-code-field { animation: none; } }

"use client";

import { useId, useState, type ComponentProps } from "react";
import { cn } from "@/lib/utils";
import "./promotion-code.css";

export type PromotionCodeProps = Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "size"> & {
  theme?: "light" | "dark";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onApply?: (code: string) => void;
  applyLabel?: string;
  loadingLabel?: string;
  loading?: boolean;
  error?: string;
  success?: boolean;
  successLabel?: string;
};

/** A compact input that expands in place when focused. */
export function PromotionCode({
  theme = "light", value, defaultValue = "", onValueChange, onApply,
  placeholder = "Add promotion code", applyLabel = "Apply",
  loadingLabel = "Applying…", loading = false, error, success = false, successLabel = "Applied",
  className, disabled, readOnly, id, onFocus, onBlur, onKeyDown,
  "aria-describedby": describedBy, ...props
}: PromotionCodeProps) {
  const uid = useId();
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [focused, setFocused] = useState(false);
  const code = value ?? internalValue;
  const expanded = focused || code.length > 0 || loading || !!error || success;
  const canApply = !!code.trim() && !disabled && !readOnly && !loading && !success;
  const errorId = `${uid}-error`;
  function apply() { if (canApply) onApply?.(code.trim()); }
  return (
    <div data-slot="promotion-code" data-theme={theme} className={cn("jui-promotion-code", className)} data-status={loading ? "loading" : error ? "error" : success ? "success" : "idle"} data-expanded={expanded} data-has-value={!!code.trim()} data-disabled={disabled || undefined} aria-busy={loading}>
      <div className="jui-promotion-code-field" onFocus={() => setFocused(true)} onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false);
      }}>
        <span className="jui-promotion-code-measure" aria-hidden="true">{placeholder}</span>
        <input {...props} id={id ?? uid} type="text" size={1} value={code}
          placeholder={placeholder} aria-label={props["aria-label"] ?? placeholder}
          aria-invalid={!!error || props["aria-invalid"]}
          aria-describedby={[describedBy, error ? errorId : null].filter(Boolean).join(" ") || undefined}
          disabled={disabled} readOnly={readOnly || loading} autoComplete={props.autoComplete ?? "off"}
          spellCheck={props.spellCheck ?? false}
          onChange={(event) => { setInternalValue(event.target.value); onValueChange?.(event.target.value); }}
          onFocus={onFocus} onBlur={onBlur}
          onKeyDown={(event) => {
            onKeyDown?.(event);
            if (event.defaultPrevented || event.nativeEvent.isComposing) return;
            if (event.key === "Enter") { event.preventDefault(); apply(); }
            if (event.key === "Escape") event.currentTarget.blur();
          }} />
        <button className="jui-promotion-code-apply" type="button" onClick={apply}
          disabled={!canApply} aria-label={loading ? loadingLabel : success ? successLabel : applyLabel} aria-hidden={!code.trim() && !loading && !success} tabIndex={code.trim() ? 0 : -1}>
          {loading ? <span className="jui-promotion-code-spinner" aria-hidden="true" /> : success ? <span className="jui-promotion-code-confirmation"><svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m3 8 3 3 7-7" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>{successLabel}</span> : applyLabel}
        </button>
      </div>
      <span className="jui-promotion-code-announcement" role="status">{loading ? loadingLabel : success && !error ? successLabel : ""}</span>
      {error && <span className="jui-promotion-code-error" id={errorId} role="alert">{error}</span>}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
